  wire [111:0] s = {e0_a[8:0], e0_b[8:0], e1_a[8:0], e2_a[8:0], e3_a[17:0], e4_a[17:0], e4_b[17:0], e5_a[0:0], e6_a[8:0], e7_a[8:0], 3'b0};
  reg [4:0] u = 0;
  reg [1791:0] rec = 0;
  localparam REC = 0, SEND = 1;
  reg state = REC;
  function [7:0] hex(input [3:0] v);
    hex = v < 10 ? 8'h30 + v : 8'h37 + v;
  endfunction
  localparam N = 448;
  reg [9:0] ci = 0;
  reg [7:0] ch;
  always @* begin
    if (ci == 0) ch = "B";
    else if (ci < N + 1) ch = hex(rec[1791 - 4 * (ci - 1) -: 4]);
    else if (ci == N + 1) ch = 8'h0d;
    else ch = 8'h0a;
  end
  reg tx = 1, busy = 0;
  reg [7:0] baud = 0;
  reg [3:0] bitn = 0;
  reg [9:0] shift = 10'h3ff;
  always @(posedge clk_25mhz)
    case (state)
      REC: begin
        rec <= {rec[1679:0], s};
        u <= u + 1;
        if (u == 15) state <= SEND;
      end
      SEND:
        if (!busy) begin
          shift <= {1'b1, ch, 1'b0};
          busy <= 1; baud <= 0; bitn <= 0;
        end else if (baud == 216) begin
          baud <= 0;
          tx <= shift[0];
          shift <= {1'b1, shift[9:1]};
          bitn <= bitn + 1;
          if (bitn == 9) begin
            busy <= 0;
            if (ci == N + 2) ci <= 0;
            else ci <= ci + 1;
          end
        end else baud <= baud + 1;
    endcase
  assign ftdi_rxd = tx;
